import{_ as a,o as s,c as e,ai as o}from"./chunks/framework.BBSijY9B.js";const h=JSON.parse('{"title":"邮件和消息为什么先出草稿","description":"理解 Grok Bot 的\\"草稿优先\\"设计，学会审稿、改稿和放心地按下发送。","frontmatter":{"related":["/basics/safety-approvals","/basics/connectors-plugins","/roles/ops-sales"],"title":"邮件和消息为什么先出草稿","description":"理解 Grok Bot 的\\"草稿优先\\"设计，学会审稿、改稿和放心地按下发送。","section":"basics","order":4,"tags":["基础","邮件","草稿","安全"],"sources":["https://docs.x.ai/grok-bot/chat-and-collaboration","https://docs.x.ai/grok-bot/overview","https://docs.x.ai/grok-bot/approvals-security-and-privacy"],"wordCount":509,"readingTime":1,"head":[["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:title","content":"邮件和消息为什么先出草稿 | WANGXXXL"}],["meta",{"property":"og:description","content":"理解 Grok Bot 的\\"草稿优先\\"设计，学会审稿、改稿和放心地按下发送。"}],["meta",{"property":"og:url","content":"https://wangxxxl.com/basics/drafts-first"}],["meta",{"property":"og:image","content":"https://wangxxxl.com/og/basics-drafts-first-1f120b831c.png"}],["meta",{"property":"og:image:alt","content":"邮件和消息为什么先出草稿 · WANGXXXL · wangxxxl.com"}],["meta",{"name":"twitter:title","content":"邮件和消息为什么先出草稿 | WANGXXXL"}],["meta",{"name":"twitter:description","content":"理解 Grok Bot 的\\"草稿优先\\"设计，学会审稿、改稿和放心地按下发送。"}],["meta",{"name":"twitter:image","content":"https://wangxxxl.com/og/basics-drafts-first-1f120b831c.png"}],["meta",{"name":"twitter:image:alt","content":"邮件和消息为什么先出草稿 · WANGXXXL · wangxxxl.com"}],["link",{"rel":"canonical","href":"https://wangxxxl.com/basics/drafts-first"}]]},"headers":[],"relativePath":"basics/drafts-first.md","filePath":"basics/drafts-first.md","lastUpdated":1792485206000}'),n={name:"basics/drafts-first.md"};function i(p,t,l,r,c,d){return s(),e("div",null,[...t[0]||(t[0]=[o(`<h1 id="邮件和消息为什么先出草稿" tabindex="-1">邮件和消息为什么先出草稿 <a class="header-anchor" href="#邮件和消息为什么先出草稿" aria-label="Permalink to &quot;邮件和消息为什么先出草稿&quot;">​</a></h1><p>当 Bot 替你写邮件或 Slack 消息时，它默认不会直接发出去，而是在对话里给你一张<strong>可编辑的草稿卡片</strong>：收件人、标题、正文都摆在那里，由你检查后自己点发送，或者丢弃。</p><h2 id="为什么要这样设计" tabindex="-1">为什么要这样设计 <a class="header-anchor" href="#为什么要这样设计" aria-label="Permalink to &quot;为什么要这样设计&quot;">​</a></h2><p>一封发出去的邮件收不回来。Bot 再聪明，也可能：</p><ul><li>选错收件人（同名同事、旧邮箱）；</li><li>误解语气（你想委婉，它写得太直接）；</li><li>引用了过时的信息（上周的报价、已取消的会议）。</li></ul><p>草稿优先，等于在&quot;AI 写&quot;和&quot;别人看到&quot;之间留了一道你亲自把关的门。这一步只花你几秒钟，但能避免最尴尬的错误。</p><h2 id="审稿时看什么" tabindex="-1">审稿时看什么 <a class="header-anchor" href="#审稿时看什么" aria-label="Permalink to &quot;审稿时看什么&quot;">​</a></h2><p>按这个顺序扫一遍，大多数问题都能发现：</p><ol><li><strong>收件人和抄送</strong>：对不对、全不全、有没有不该出现的人。</li><li><strong>称呼和语气</strong>：符不符合你和对方的关系。</li><li><strong>事实和数字</strong>：日期、金额、名称有没有错。</li><li><strong>承诺</strong>：有没有替你答应了你没打算答应的事。</li><li><strong>附件</strong>：该带的带了没有。</li></ol><h2 id="让草稿更接近一次通过" tabindex="-1">让草稿更接近一次通过 <a class="header-anchor" href="#让草稿更接近一次通过" aria-label="Permalink to &quot;让草稿更接近一次通过&quot;">​</a></h2><p>把你的写信习惯交代给它，并请它记住：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>以后帮我写对外邮件时：</span></span>
<span class="line"><span>- 称呼用&quot;X 总&quot;或&quot;X 老师&quot;，不用&quot;亲&quot;；</span></span>
<span class="line"><span>- 正文三段以内，第一句就说明来意；</span></span>
<span class="line"><span>- 结尾不写&quot;期待您的回复&quot;，改成具体的下一步和时间；</span></span>
<span class="line"><span>- 落款用&quot;（你的名字）&quot;。</span></span>
<span class="line"><span>请记住这些习惯。</span></span></code></pre></div><p>觉得草稿不满意，直接在对话里提修改意见，让它改同一份草稿：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>第二段太啰嗦了，压缩成两句；把会议时间改成周四下午三点。改好再给我看。</span></span></code></pre></div><h2 id="批量场景也一样" tabindex="-1">批量场景也一样 <a class="header-anchor" href="#批量场景也一样" aria-label="Permalink to &quot;批量场景也一样&quot;">​</a></h2><p>要发一批跟进邮件时，可以让它一次起草多份，你逐一审核：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>给这 8 位参会者各写一封感谢邮件，每封要提到对方在会上的发言要点（见附件纪要）。</span></span>
<span class="line"><span>全部做成草稿，我逐封确认后再发。</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title">草稿卡片在哪里</p><p>草稿会出现在你和这个 Bot 的一对一对话里。群聊中不会出现邮件草稿和审批卡片，所以涉及对外发送的事，最好在一对一对话里交代。</p></div><div class="warning custom-block"><p class="custom-block-title">别为了省事关掉门槛</p><p>有人嫌每次点发送麻烦，想让 Bot 直接发。对内部、低风险的通知可以考虑；对客户、合作方、上级的消息，强烈建议保留人工确认。</p></div>`,19)])])}const u=a(n,[["render",i]]);export{h as __pageData,u as default};
